def f(xs):
    if len(xs) >= 2 and xs[0] == xs[1]:
        return xs[2:]
    if len(xs) >= 2 and xs[-2] == xs[-1]:
        return xs[:-2]
    return xs[:]

def f(xs):
    seen = set()
    total = 0
    out = []
    for x in xs:
        if x not in seen:
            seen.add(x)
            total += x
            out.append(total)
    return out
